export const FIELD_TYPE_INVENTORY = Object.freeze({ SELECT_SINGLE: 15, SELECT_MULTI: 1, TEXT_SHORT: 15, TEXT_LONG: 2, STRUCTURED_REPEAT: 14 });

export function enrichManualFields(fields) {
  return fields.map(field => Object.freeze({
    ...field,
    manualType: field.kind === "enum" ? "SELECT_SINGLE" : field.kind === "enum-list" ? "SELECT_MULTI" : field.kind === "text" ? "TEXT_SHORT" : field.kind === "textarea" ? "TEXT_LONG" : "STRUCTURED_REPEAT",
    help: Object.freeze({
      ...field.help,
      examples: TEXT_EXAMPLES[field.canonicalPath] || field.help?.examples || [],
      optionDetails: SELECT_OPTION_DETAILS[field.canonicalPath] || [],
      structuredGuide: STRUCTURED_GUIDES[field.canonicalPath] || null,
    }),
  }));
}

