export const EXPERT_GLOSSARY = Object.freeze([
  ["Canonical","その文脈で正式な参照対象として扱われる状態。単なる保存とは異なる。","A state treated as the formal reference in its context; it is not ordinary saving."],
  ["Revision","Characterの保存版を区別する識別値。保存時に自動生成される。","An identifier distinguishing saved Character versions, generated when saving."],
  ["Digest","内容が変わっていないか確認するための計算値。通常のPackage ImportではBuilderが確認する。","A calculated value used to check content integrity; Builder verifies it during ordinary Package import."],
  ["Conformance","保持、逸脱、継続性など、定義された条件への適合を確認すること。","Checking compliance with defined preservation, drift, and continuity conditions."],
  ["Adoption","上位の契約や組織が対象を正式に採用すること。Builder Saveとは異なる。","Formal adoption by an applicable contract or organization; it differs from Builder Save."],
  ["Authority","実在する人や組織の権限。Characterの役割やSeat8の記述だけでは発生しない。","Authority held by a real person or organization; it is not created by a Character role or Seat 8 text."],
].map(([term,ja,en]) => Object.freeze({ term, description:l(ja,en) })));

